3_SERVER;				$this->sslContext = \stream_context_create( [			'ssl' => [				'local_cert'        => $this->certPath				,'local_pk'         => "{$localSslCert}/darkweb.fr.key" // si séparée//				,'passphrase'        => 'motdepasse' // si clé chiffrée				,'verify_peer'       => false 				,'allow_self_signed' => true//				,'crypto_method' =>  $cryptoMethods//				,'SNI_server_name'	 => 'darkweb.fr'// optionnel, SNI			]		] );	}		public function init(  ) : void {		$this->getDwStreamSelect()->getProcDwResources()->fileRead( $this->certPath, new DwCallBack( array( &$this ,"checkCertAlgoSupported" ) ) );		//parent::init();	}	public function checkCertAlgoSupported( string $certData ) {		if ($certData === false) throw new \Exception("Certificat non lisible : $certPath");				$x509 = \openssl_x509_parse($certData);		if ($x509 === false) throw new \Exception("Impossible de parser le certificat : $certPath");				// Détecter l’algo de clé publique		$pubkey = \openssl_pkey_get_public($certData);		$keyDetails = \openssl_pkey_get_details($pubkey);				if (isset($keyDetails['type'])) {			$algo = $keyDetails['type'];			// Typiquement : OPENSSL_KEYTYPE_RSA, OPENSSL_KEYTYPE_EC, etc.			if ($algo == OPENSSL_KEYTYPE_EC) {				// Test support EC (ECDSA)				if (!in_array('ec', openssl_get_cipher_methods()))					throw new \Exception("Certificat EC/ECDSA détecté, mais EC non supporté par ce build PHP/openssl.");							} elseif ($algo == OPENSSL_KEYTYPE_RSA) {				// Tout va bien, RSA supporté			} else {				throw new \Exception("Type de clé non supporté ou inconnu : algo type $algo");			}		} else {			throw new \Exception("Impossible de déterminer le type de clé du certificat !");		}		$this->listenSock( );	}	protected function listenSock( ) {		if ( $this->isListen )			throw new \Exception("is ever in listen");		else {			$dwIp = $this->dwPort->getIp();			if ( \bakuba\kernel\network\DwIp6::getStaticClassName() == $dwIp->getClassName() )				$ipAdress = "[{$dwIp->getIpAddress()}]";			else				$ipAdress = $dwIp->getIpAddress();			$port=$this->dwPort->getPort();			$this->listen( "tls://{$ipAdress}:$port" );			$this->isListen = true;		}	}	/*	protected function createDwStreamSocket( $sock ) : DwStreamSocket {		return new DwStreamSocket( $this ,$this->dwInterface ,$sock );	}	//*/	/*	public function acceptTcpConnection( DwStreamSocket $dwStreamSocketAccept ) : void {		$this->log->trace(".");		$sockListen = $dwStreamSocketAccept->getResource();		$sock = @\stream_socket_accept( $sockListen );		if ( $sock === false )			throw new \Exception( "failed(sock:false) to stream_socket_accept" );		elseif ( $sock !== null ) {			$dwStreamSocket = $this->createDwStreamSocket( $sock );			$dwStreamSocket->connectedReadPeer();			$this->dwResources->addTimer( 				0.5				,new DwCallBack(					array( &$this ,"newConnection" )					,$dwStreamSocket				)			);		} else 			throw new \Exception( "failed to socket_accept sock not false but null" );	}	//*/	/*	public function newConnection( DwStreamSocket $dwStreamSocket ,int $cpt = 0 ) : void {		$this->log->info( " Try Stream ssl test n:$cpt" );				$result = \stream_socket_enable_crypto(			$dwStreamSocket->getResource()			,true			,\STREAM_CRYPTO_METHOD_TLS_SERVER | \STREAM_CRYPTO_METHOD_TLSv1_2_SERVER | \STREAM_CRYPTO_METHOD_TLSv1_3_SERVER// ou CLIENT selon cas		);		$this->log->info( "ssl error string" );		$this->log->info( \openssl_error_string() );		$this->log->info( "ssl error get last" );		$this->log->info( \error_get_last() );		if ( $result === 0 ) {			$this->log->info( "ReTry SSL :".print_r( $result ,true ) );			//$dwStreamSocket->enableListen();// enable listen for no read action			if ( $cpt > 20 )				$this->log->info( "ReTry SSL : STOP after $cpt tentatives..." );			else				$this->dwResources->addTimer(					0.2					,new DwCallBack(						array( &$this ,"newConnection" )						,$dwStreamSocket						,$cpt++					)				);		} else {			//$dwStreamSocket->disableListen();			if ( $result === true ) {				$this->log->info( "Try SSL :".print_r( $result ,true ) );			} else {				$this->log->info( "Not SSL :".print_r( is_null( $result ) ? "null" : $result, true ) );			}						new DwServerConnexion(				$this->parent				,new \bakuba\kernel\io\stream\DwStreamSocketIpConnexion (					$this->dwStreamSelect					,$dwStreamSocket					,$this->dwPort					,$dwStreamSocket->getDwPort()				) 			);		}	}	//*/	///*	public function __destruct() {		//$this->log->trace( "." );		foreach( $this as $key => $toDestruct )			if ( isset( $this->$key ) ) unset( $this->$key );		parent::__destruct();	}	//*/	public function getClassName( bool $fqcn=null ) : string {		return self::getStaticClassName( $fqcn );	}	public static function getStaticClassName( bool $fqcn=null ) : string {		return $fqcn ? parent::getStaticClassName( $fqcn ).self::CLASS_SEPARATOR.__CLASS__ : __CLASS__;	}}?>